<?php
require_once __DIR__ . '/../../../backend/config/database.php';
require_once __DIR__ . '/../../../backend/helpers/functions.php';
require_once __DIR__ . '/../../../backend/auth.php';
portal_require_auth(['admin', 'humas']);

function career_unique_slug(PDO $pdo, string $title, int $ignoreId = 0): string {
    $base = portal_slug($title); $slug = $base; $counter = 2;
    $stmt = $pdo->prepare('SELECT COUNT(*) FROM job_vacancies WHERE slug=? AND id<>?');
    while (true) { $stmt->execute([$slug,$ignoreId]); if ((int)$stmt->fetchColumn() === 0) return $slug; $slug = $base . '-' . $counter++; }
}

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    portal_verify_csrf();
    $action = $_POST['action'] ?? '';
    try {
        if ($action === 'save_job') {
            $id=(int)($_POST['id']??0); $title=trim($_POST['title']??''); $unit=trim($_POST['unit']??''); $department=trim($_POST['department']??'');
            $employmentType=trim($_POST['employment_type']??''); $location=trim($_POST['work_location']??''); $summary=trim($_POST['summary']??'');
            $description=trim($_POST['description']??''); $responsibilities=trim($_POST['responsibilities']??''); $requirements=trim($_POST['requirements']??'');
            if ($title===''||$unit===''||$department===''||$employmentType===''||$location===''||$summary===''||$description===''||$responsibilities===''||$requirements==='') throw new RuntimeException('Kolom utama, deskripsi, tanggung jawab, dan kualifikasi wajib diisi.');
            $slug=career_unique_slug($pdo,$title,$id);
            $previousImage=null; $image=null;
            if ($id) { $imageStmt=$pdo->prepare('SELECT image FROM job_vacancies WHERE id=?'); $imageStmt->execute([$id]); $previousImage=$imageStmt->fetchColumn()?:null; $image=$previousImage; }
            if (!empty($_FILES['image']['name'])) $image=portal_upload_image($_FILES['image'],'karir');
            $values=[$title,$slug,$unit,$department,$employmentType,$location,trim($_POST['education']??'')?:null,trim($_POST['experience']??'')?:null,$summary,$description,$responsibilities,$requirements,trim($_POST['benefits']??'')?:null,trim($_POST['salary_note']??'')?:null,$image,($_POST['deadline']??'')?:null,isset($_POST['is_featured'])?1:0,isset($_POST['is_active'])?1:0];
            if ($id) { $stmt=$pdo->prepare('UPDATE job_vacancies SET title=?,slug=?,unit=?,department=?,employment_type=?,work_location=?,education=?,experience=?,summary=?,description=?,responsibilities=?,requirements=?,benefits=?,salary_note=?,image=?,deadline=?,is_featured=?,is_active=? WHERE id=?'); $values[]=$id; $stmt->execute($values); if($previousImage&&$previousImage!==$image) portal_delete_uploaded_image($previousImage); portal_log($pdo,'update_job','Memperbarui lowongan: '.$title); }
            else { $stmt=$pdo->prepare('INSERT INTO job_vacancies (title,slug,unit,department,employment_type,work_location,education,experience,summary,description,responsibilities,requirements,benefits,salary_note,image,deadline,is_featured,is_active) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)'); $stmt->execute($values); portal_log($pdo,'create_job','Menerbitkan lowongan: '.$title); }
            portal_flash('success','Lowongan berhasil disimpan dan halaman Karir sudah diperbarui.');
        } elseif ($action === 'delete_job') {
            $id=(int)($_POST['id']??0); $stmt=$pdo->prepare('SELECT title,(SELECT COUNT(*) FROM job_applications WHERE vacancy_id=job_vacancies.id) applications FROM job_vacancies WHERE id=?'); $stmt->execute([$id]); $job=$stmt->fetch();
            if ($job) { if((int)$job['applications']>0){$pdo->prepare('UPDATE job_vacancies SET is_active=0 WHERE id=?')->execute([$id]); portal_flash('success','Lowongan diarsipkan karena sudah memiliki data pelamar.');}else{$pdo->prepare('DELETE FROM job_vacancies WHERE id=?')->execute([$id]); portal_flash('success','Lowongan berhasil dihapus.');} portal_log($pdo,'delete_job','Menghapus/mengarsipkan lowongan: '.$job['title']); }
        } elseif ($action === 'update_application') {
            $id=(int)($_POST['id']??0); $status=$_POST['status']??'baru'; if(!in_array($status,['baru','ditinjau','wawancara','diterima','ditolak'],true)) throw new RuntimeException('Status kandidat tidak valid.');
            $pdo->prepare('UPDATE job_applications SET status=?,admin_notes=? WHERE id=?')->execute([$status,trim($_POST['admin_notes']??'')?:null,$id]);
            portal_log($pdo,'update_application','Memperbarui status lamaran #'.$id.' menjadi '.$status); portal_flash('success','Status dan catatan kandidat berhasil diperbarui.');
        }
    } catch (Throwable $e) { portal_flash('danger',$e->getMessage()); }
    header('Location: '.SITE_URL.'/portal/careers'); exit;
}

$editJob=null; if(isset($_GET['edit'])){$stmt=$pdo->prepare('SELECT * FROM job_vacancies WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$editJob=$stmt->fetch()?:null;}
$viewApplication=null; if(isset($_GET['application'])){$stmt=$pdo->prepare('SELECT a.*,v.title job_title FROM job_applications a JOIN job_vacancies v ON v.id=a.vacancy_id WHERE a.id=?');$stmt->execute([(int)$_GET['application']]);$viewApplication=$stmt->fetch()?:null;}
$showJobForm=isset($_GET['new'])||$editJob;
$jobs=$pdo->query('SELECT v.*,(SELECT COUNT(*) FROM job_applications a WHERE a.vacancy_id=v.id) application_count FROM job_vacancies v ORDER BY v.is_active DESC,v.is_featured DESC,v.created_at DESC')->fetchAll();
$applicationStatus=$_GET['status']??''; $applicationWhere='';$applicationParams=[]; if(in_array($applicationStatus,['baru','ditinjau','wawancara','diterima','ditolak'],true)){$applicationWhere=' WHERE a.status=?';$applicationParams[]=$applicationStatus;}
$stmt=$pdo->prepare('SELECT a.*,v.title job_title FROM job_applications a JOIN job_vacancies v ON v.id=a.vacancy_id'.$applicationWhere.' ORDER BY a.created_at DESC');$stmt->execute($applicationParams);$applications=$stmt->fetchAll();
$summary=$pdo->query("SELECT COUNT(*) total,SUM(status='baru') new_count,SUM(status='wawancara') interview_count,SUM(status='diterima') accepted_count FROM job_applications")->fetch();
$statusLabels=['baru'=>'Baru','ditinjau'=>'Ditinjau','wawancara'=>'Wawancara','diterima'=>'Diterima','ditolak'=>'Ditolak'];
$portalTitle='Karir & Lamaran';$portalActive='careers';require __DIR__.'/../../components/portal-header.php';
?>

