<div class="stat-grid"><div class="stat-card"><small>Lowongan</small><strong><?php echo count($jobs); ?></strong><span>Total data</span></div><div class="stat-card"><small>Pelamar</small><strong><?php echo (int)$summary['total']; ?></strong><span>Semua posisi</span></div><div class="stat-card"><small>Lamaran baru</small><strong><?php echo (int)$summary['new_count']; ?></strong><span>Perlu ditinjau</span></div><div class="stat-card"><small>Tahap wawancara</small><strong><?php echo (int)$summary['interview_count']; ?></strong><span>Kandidat aktif</span></div></div>

